<template><main class="community-page"><section class="community-hero"><div class="page-shell"><p class="eyebrow">CUSTOMER SUPPORT</p><h1>Q&amp;A</h1><p>상품과 주문에 관한 궁금한 점을 편하게 남겨주세요.</p></div></section><div class="qna-shell page-shell"><div class="qna-guide"><div><i class="fa-regular fa-comments"></i><p><strong>궁금한 점이 있으신가요?</strong><span>영업일 기준 순차적으로 답변해 드립니다.</span></p></div><RouterLink v-if="isAuthenticated" to="/qna/create">문의 작성 <i class="fa-solid fa-pen"></i></RouterLink><RouterLink v-else to="/login">로그인 후 문의하기</RouterLink></div><div class="qna-categories"><button v-for="category in categories" :key="category" :class="{active:selectedCategory===category}" @click="changeCategory(category)">{{category}}</button></div><form class="qna-search" @submit.prevent="fetchQnas"><select v-model="searchType" aria-label="검색 범위"><option value="title">제목</option><option value="content">내용</option><option value="title_content">제목+내용</option><option value="author">작성자</option></select><label><i class="fa-solid fa-magnifying-glass"></i><input v-model.trim="searchKeyword" placeholder="검색어를 입력하세요" /></label><button>검색</button></form><div v-if="isLoading" class="community-loading"><span></span><p>문의 내역을 불러오고 있습니다.</p></div><div v-else-if="!isAuthenticated" class="community-empty"><i class="fa-solid fa-lock"></i><h2>로그인이 필요한 서비스입니다.</h2><p>로그인 후 문의를 확인하고 작성할 수 있습니다.</p><RouterLink to="/login">로그인</RouterLink></div><div v-else-if="qnaList.length" class="qna-list"><article v-for="(item,index) in qnaList" :key="item._id" @click="goDetail(item._id)"><span class="qna-number">{{String((currentPage-1)*pageSize+index+1).padStart(2,'0')}}</span><div class="qna-main"><div><span class="qna-category">{{item.category}}</span><span :class="['qna-status',{answered:item.hasAnswer}]">{{item.hasAnswer?'답변완료':'답변대기'}}</span></div><h2>{{item.title}}</h2><p>{{item.productName||'일반 문의'}}</p></div><div class="qna-meta"><span>{{item.maskedAuthor}}</span><time>{{formatDate(item.createdAt)}}</time><span>조회 {{item.views||0}}</span></div><i class="fa-solid fa-chevron-right"></i></article></div><div v-else class="community-empty"><i class="fa-regular fa-comments"></i><h2>등록된 문의가 없습니다.</h2><p>궁금한 점을 첫 번째로 남겨보세요.</p></div><Pagination v-if="totalPages>1" :current-page="currentPage" :total-pages="totalPages" @page-change="changePage" /></div></main></template>
<script setup>import{computed,onMounted,ref}from"vue";import{useRouter}from"vue-router";import QnaService from"@/api/QnaService";import Pagination from"@/components/common/Pagination.vue";const router=useRouter(),categories=["전체","상품","주문","결제","배송","기타"],selectedCategory=ref("전체"),qnaList=ref([]),searchType=ref("title"),searchKeyword=ref(""),currentPage=ref(1),totalPages=ref(1),isLoading=ref(false),pageSize=8;const token=localStorage.getItem("token"),user=JSON.parse(localStorage.getItem("user")||"null"),isAuthenticated=computed(()=>Boolean(token&&user?._id));const fetchQnas=async()=>{if(!isAuthenticated.value)return;isLoading.value=true;try{const response=await QnaService.getQnaList({userId:user._id,category:selectedCategory.value==="전체"?"":selectedCategory.value,searchType:searchType.value,keyword:searchKeyword.value,page:currentPage.value,size:pageSize},token);qnaList.value=response.data.qnas||[];totalPages.value=Math.max(1,Math.ceil(Number(response.data.total||0)/pageSize))}catch(error){console.error(error);qnaList.value=[]}finally{isLoading.value=false}};const changeCategory=value=>{selectedCategory.value=value;currentPage.value=1;fetchQnas()};const changePage=value=>{currentPage.value=value;fetchQnas()};const goDetail=id=>router.push({name:"QnADetail",params:{id}});const formatDate=value=>value?new Date(value).toLocaleDateString("ko-KR",{year:"numeric",month:"2-digit",day:"2-digit"}):"-";onMounted(fetchQnas);</script>
<style>.qna-shell{padding-block:55px 110px}.qna-guide{display:flex;align-items:center;justify-content:space-between;padding:25px 30px;color:#fff;background:#332c30}.qna-guide>div{display:flex;align-items:center;gap:16px}.qna-guide>div>i{color:#d2a5ad;font-size:1.4rem}.qna-guide strong,.qna-guide span{display:block}.qna-guide strong{font-size:.82rem}.qna-guide span{margin-top:3px;color:#afa4a9;font-size:.65rem}.qna-guide>a{padding:11px 16px;border:1px solid #675b61;font-size:.68rem}.qna-guide>a i{margin-left:8px}.qna-categories{display:flex;gap:4px;margin-top:35px;border-bottom:1px solid var(--color-line)}.qna-categories button{padding:11px 18px;border:0;border-bottom:2px solid transparent;background:#fff;color:#8d8388;font-size:.72rem}.qna-categories button.active{border-bottom-color:var(--color-brand);color:var(--color-brand-dark);font-weight:800}.qna-search{display:flex;justify-content:flex-end;gap:8px;padding:22px 0}.qna-search select{width:110px;padding:0 10px;border:1px solid #ddd5d8;background:#fff;font-size:.68rem}.qna-search label{width:240px;display:flex;align-items:center;gap:8px;padding:9px 12px;border:1px solid #ddd5d8}.qna-search input{width:100%;border:0;outline:0;font-size:.7rem}.qna-search button{padding:0 18px;border:0;color:#fff;background:var(--color-brand-dark);font-size:.7rem}.qna-list{border-top:1px solid #342e31}.qna-list article{display:grid;grid-template-columns:45px 1fr 190px 15px;align-items:center;gap:20px;padding:23px 12px;border-bottom:1px solid var(--color-line);cursor:pointer}.qna-list article:hover{background:#fbf8f6}.qna-number{color:#b0a6ab;font-family:Georgia,serif;font-size:.75rem}.qna-category,.qna-status{display:inline-block;padding:3px 7px;font-size:.55rem}.qna-category{margin-right:5px;color:#776d72;background:#f1edeb}.qna-status{color:#a16a73;background:#f8ecee}.qna-status.answered{color:#62796b;background:#eaf1ec}.qna-main h2{margin:7px 0 3px;font-size:.83rem}.qna-main p{color:#9a9095;font-size:.62rem}.qna-meta{display:flex;gap:12px;color:#9d9398;font-size:.61rem}.qna-list article>i{color:#b0a6aa;font-size:.55rem}.community-empty>a{display:inline-block;margin-top:20px;padding:10px 17px;color:#fff;background:var(--color-brand-dark);font-size:.7rem}@media(max-width:700px){.qna-shell{padding-top:30px}.qna-guide{align-items:flex-start;flex-direction:column;gap:18px}.qna-categories{overflow-x:auto}.qna-categories button{flex:0 0 auto}.qna-search{display:grid;grid-template-columns:100px 1fr}.qna-search label{width:auto}.qna-search button{grid-column:1/-1;height:40px}.qna-list article{grid-template-columns:30px 1fr 12px;gap:10px}.qna-meta{grid-column:2;grid-row:2}.qna-meta span:first-child,.qna-meta span:last-child{display:none}}
</style>
